import{C as e,P as t,S as n,i as r}from"./app-CJ3ltvm-.js";var i=JSON.parse(`{"path":"/document/database/%E3%80%8AMySQL%E6%95%B0%E6%8D%AE%E5%BA%93%E5%85%A5%E9%97%A8%E5%88%B0%E5%A4%A7%E7%89%9B%E3%80%8B/%E5%9F%BA%E7%A1%80%E7%AB%A0%E8%8A%82/operator.html","title":"第04章_运算符","lang":"zh-CN","frontmatter":{"title":"第04章_运算符","icon":"circle-info","order":4,"category":["数据库"],"tag":["数据库"],"date":"2023-08-29T00:00:00.000Z","isOriginal":true,"pageview":true,"article":true,"breadcrumb":false,"comment":true,"feed":false,"seo":false,"head":[["link",{"rel":"canonical","href":"https://liuchenyang.top/document/database/%E3%80%8AMySQL%E6%95%B0%E6%8D%AE%E5%BA%93%E5%85%A5%E9%97%A8%E5%88%B0%E5%A4%A7%E7%89%9B%E3%80%8B/%E5%9F%BA%E7%A1%80%E7%AB%A0%E8%8A%82/operator.html"}]]},"git":{"createdTime":1737021380000,"updatedTime":1788439109000,"contributors":[{"name":"liuchenyang","username":"liuchenyang","email":"2162059863@qq.com","commits":3,"url":"https://github.com/liuchenyang"}]},"readingTime":{"minutes":19.73,"words":5919},"filePathRelative":"document/database/《MySQL数据库入门到大牛》/基础章节/operator.md","copyright":"著作权归 Mr.Liucy 所有，本站内容遵循 MIT 协议，转载请注明出处。\\n原文链接：https://liuchenyang.top/document/database/%E3%80%8AMySQL%E6%95%B0%E6%8D%AE%E5%BA%93%E5%85%A5%E9%97%A8%E5%88%B0%E5%A4%A7%E7%89%9B%E3%80%8B/%E5%9F%BA%E7%A1%80%E7%AB%A0%E8%8A%82/operator.html"}`),a={name:`operator.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<div class="hint-container tip"><p class="hint-container-title">友情提示</p><p><strong>转载须知</strong>: 以下所有文章整理于B站宋红康老师的《MySQL数据库入门到大牛》。<a href="https://www.bilibili.com/video/BV1iq4y1u7vj?p=1&amp;vd_source=cea816a08805c218ac4390ae9b61ae31" target="_blank" rel="noopener noreferrer">MySQL</a></p></div><h2 id="_1-算术运算符" tabindex="-1"><a class="header-anchor" href="#_1-算术运算符"><span>1. 算术运算符</span></a></h2><p>算术运算符主要用于数学运算，其可以连接运算符前后的两个数值或表达式，对数值或表达式进行加（+）、减（-）、乘（*）、除（/）和取模（%）运算。</p><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012100749193.png" alt="image-20211012100749193" tabindex="0" loading="lazy"><figcaption>image-20211012100749193</figcaption></figure><p><strong>1．加法与减法运算符</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">35</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">35</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> dual;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----+---------+---------+----------+--------------+------------+------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">35</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> - </span><span style="color:#D19A66;">35</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----+---------+---------+----------+--------------+------------+------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">150</span><span style="color:#ABB2BF;"> |          </span><span style="color:#D19A66;">120</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">135</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> |       </span><span style="color:#D19A66;">64</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----+---------+---------+----------+--------------+------------+------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>由运算结果可以得出如下结论：</p><blockquote><ul><li>一个整数类型的值对整数进行加法和减法操作，结果还是一个整数；</li><li>一个整数类型的值对浮点数进行加法和减法操作，结果是一个浮点数；</li><li>加法和减法的优先级相同，进行先加后减操作与进行先减后加操作的结果是一样的；</li><li>在Java中，+的左右两边如果有字符串，那么表示字符串的拼接。但是在MySQL中+只表示数值相加。如果遇到非数值类型，先尝试转成数值，如果转失败，就按0计算。（补充：MySQL中字符串拼接要使用字符串函数CONCAT()实现）</li></ul></blockquote><p><strong>2．乘法与除法运算符</strong></p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> /</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> DIV </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> dual;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----+---------+-----------+-----------+---------+-----------------+---------+-----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> * </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> / </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> /</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">  | </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> DIV </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----+---------+-----------+-----------+---------+-----------------+---------+-----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |  </span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0000</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">50</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0000</span><span style="color:#ABB2BF;"> |        </span><span style="color:#D19A66;">105</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">0000</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">33</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">3333</span><span style="color:#ABB2BF;"> |      </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----+---------+-----------+-----------+---------+-----------------+---------+-----------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#计算出员工的年基本工资</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,salary,salary * </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> annual_sal </span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>由运算结果可以得出如下结论：</p><blockquote><ul><li>一个数乘以整数1和除以整数1后仍得原数；</li><li>一个数乘以浮点数1和除以浮点数1后变成浮点数，数值与原数相等；</li><li>一个数除以整数后，不管是否能除尽，结果都为一个浮点数；</li><li>一个数除以另一个数，除不尽时，结果为一个浮点数，并保留到小数点后4位；</li><li>乘法和除法的优先级相同，进行先乘后除操作与先除后乘操作，得出的结果相同。</li><li>在数学运算中，0不能用作除数，在MySQL中，一个数除以0为NULL。</li></ul></blockquote><p><strong>3．求模（求余）运算符</strong><br> 将t22表中的字段i对3和5进行求模（求余）运算。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 12</span><span style="color:#ABB2BF;"> % </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> MOD </span><span style="color:#D19A66;">5</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> dual;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> % </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> MOD </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |        </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+----------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#筛选出employee_id是偶数的员工</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> employee_id MOD </span><span style="color:#D19A66;">2</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可以看到，100对3求模后的结果为3，对5求模后的结果为0。</p><h2 id="_2-比较运算符" tabindex="-1"><a class="header-anchor" href="#_2-比较运算符"><span>2. 比较运算符</span></a></h2><p>比较运算符用来对表达式左边的操作数和右边的操作数进行比较，比较的结果为真则返回1，比较的结果为假则返回0，其他情况则返回NULL。</p><p>比较运算符经常被用来作为SELECT查询语句的条件来使用，返回符合条件的结果记录。</p><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012101110021.png" alt="image-20211012101110021"><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012104955094.png" alt="image-20211012104955094" tabindex="0" loading="lazy"><figcaption>image-20211012104955094</figcaption></figure><p><strong>1．等号运算符</strong></p><ul><li><p>等号运算符（=）判断等号两边的值、字符串或表达式是否相等，如果相等则返回1，不相等则返回0。</p></li><li><p>在使用等号运算符时，遵循如下规则：</p><ul><li>如果等号两边的值、字符串或表达式都为字符串，则MySQL会按照字符串进行比较，其比较的是每个字符串中字符的ANSI编码是否相等。</li><li>如果等号两边的值都是整数，则MySQL会按照整数来比较两个值的大小。</li><li>如果等号两边的值一个是整数，另一个是字符串，则MySQL会将字符串转化为数字进行比较。</li><li>如果等号两边的值、字符串或表达式中有一个为NULL，则比较结果为NULL。</li></ul></li><li><p>对比：SQL中赋值符号使用 :=</p></li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;1&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#ABB2BF;">, (</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> , </span><span style="color:#C678DD;">NULL</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">; </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+---------+-------+-----------+-------------------+-----------+-------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;1&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#ABB2BF;"> | (</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">) | </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NULL</span><span style="color:#56B6C2;"> =</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+---------+-------+-----------+-------------------+-----------+-------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|    </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">  |     </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">   |   </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">   |      </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">    |             </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">     |    </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">   |        </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">  |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+---------+-------+-----------+-------------------+-----------+-------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> dual;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+-----------+-----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">0</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+-----------+-----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|     </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |         </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |         </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+-----------+-----------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> warnings (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#查询salary</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">10000</span><span style="color:#ABB2BF;">，注意在Java中比较是</span><span style="color:#56B6C2;">==</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 10000</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2．安全等于运算符</strong><br> 安全等于运算符（&lt;=&gt;）与等于运算符（=）的作用是相似的，<code>唯一的区别</code>是‘&lt;=&gt;’可以用来对NULL进行判断。在两个操作数均为NULL时，其返回值为1，而不为NULL；当一个操作数为NULL时，其返回值为0，而不为NULL。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#98C379;"> &#39;1&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#ABB2BF;">, (</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">,</span><span style="color:#C678DD;">NULL</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> dual;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------+---------+-------------+---------------------+-------------+---------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#98C379;"> &#39;1&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#ABB2BF;"> | (</span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> + </span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">) | </span><span style="color:#98C379;">&#39;&#39;</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NULL</span><span style="color:#56B6C2;"> &lt;=&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------+---------+-------------+---------------------+-------------+---------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|         </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |       </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |           </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |                   </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |           </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |             </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------+---------+-------------+---------------------+-------------+---------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#</span><span style="color:#D19A66;">查询commission_pct等于0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">40</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">40</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">40</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">#</span><span style="color:#D19A66;">如果把0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">40改成</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> 呢？</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可以看到，使用安全等于运算符时，两边的操作数的值都为NULL时，返回的结果为1而不是NULL，其他返回结果与等于运算符相同。</p><p><strong>3．不等于运算符</strong><br> 不等于运算符（&lt;&gt;和!=）用于判断两边的数字、字符串或者表达式的值是否不相等，如果不相等则返回1，相等则返回0。不等于运算符不能判断NULL值。如果两边的值有任意一个为NULL，或两边都为NULL，则结果为NULL。<br> SQL语句示例如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> !=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> !=</span><span style="color:#98C379;"> &#39;b&#39;</span><span style="color:#ABB2BF;">, (</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;&gt;</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> !=</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NULL</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">; </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+------------+----------------+-------------+--------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> !=</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> !=</span><span style="color:#98C379;"> &#39;b&#39;</span><span style="color:#ABB2BF;"> | (</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">) </span><span style="color:#56B6C2;">&lt;&gt;</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">6</span><span style="color:#ABB2BF;">) | </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#56B6C2;"> !=</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NULL</span><span style="color:#56B6C2;"> &lt;&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+------------+----------------+-------------+--------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |   </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">    |       </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">    |            </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">   |     </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">    |         </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+------------+----------------+-------------+--------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>此外，还有非符号类型的运算符：</p><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012105303219.png" alt="image-20211012105303219" tabindex="0" loading="lazy"><figcaption>image-20211012105303219</figcaption></figure><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012105030527.png" alt="image-20211012105030527" tabindex="0" loading="lazy"><figcaption>image-20211012105030527</figcaption></figure><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012105052456.png" alt="image-20211012105052456" tabindex="0" loading="lazy"><figcaption>image-20211012105052456</figcaption></figure><p><strong>4. 空运算符</strong><br> 空运算符（IS NULL或者ISNULL）判断一个值是否为NULL，如果为NULL则返回1，否则返回0。<br> SQL语句示例如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> NULL</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#56B6C2;">ISNULL</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">), </span><span style="color:#56B6C2;">ISNULL</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------+--------------+-------------+-----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#C678DD;">NULL</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#56B6C2;">ISNULL</span><span style="color:#ABB2BF;">(</span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">) | </span><span style="color:#56B6C2;">ISNULL</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">) | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------+--------------+-------------+-----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|            </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |            </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |           </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |         </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------+--------------+-------------+-----------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#查询commission_pct等于NULL。比较如下的四种写法</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#56B6C2;"> ISNULL</span><span style="color:#ABB2BF;">(commission_pct);</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#56B6C2;">=</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> last_name, manager_id</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  manager_id </span><span style="color:#C678DD;">IS</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>5. 非空运算符</strong><br> 非空运算符（IS NOT NULL）判断一个值是否不为NULL，如果不为NULL则返回1，否则返回0。<br> SQL语句示例如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> NULL</span><span style="color:#C678DD;"> IS NOT NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#C678DD;"> IS NOT NULL</span><span style="color:#ABB2BF;">,  </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> IS NOT NULL</span><span style="color:#ABB2BF;">; </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------+-----------------+---------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#C678DD;">NULL</span><span style="color:#C678DD;"> IS NOT NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#C678DD;"> IS NOT NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> IS NOT NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------+-----------------+---------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |               </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |             </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------+-----------------+---------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">01</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#查询commission_pct不等于NULL</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#C678DD;">IS NOT NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> NOT</span><span style="color:#ABB2BF;"> commission_pct </span><span style="color:#56B6C2;">&lt;=&gt;</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,commission_pct </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> NOT</span><span style="color:#56B6C2;"> ISNULL</span><span style="color:#ABB2BF;">(commission_pct);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>6. 最小值运算符</strong><br> 语法格式为：LEAST(值1，值2，...，值n)。其中，“值n”表示参数列表中有n个值。在有两个或多个参数的情况下，返回最小值。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#56B6C2;"> LEAST</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">), </span><span style="color:#56B6C2;">LEAST</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#56B6C2;">LEAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------------+--------------------+-----------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#56B6C2;">LEAST</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) | </span><span style="color:#56B6C2;">LEAST</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">) | </span><span style="color:#56B6C2;">LEAST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------------+--------------------+-----------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|       </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">       |        a           |      </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">       |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------------+--------------------+-----------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>由结果可以看到，当参数是整数或者浮点数时，LEAST将返回其中最小的值；当参数为字符串时，返回字母表中顺序最靠前的字符；当比较值列表中有NULL时，不能判断大小，返回值为NULL。</p><p><strong>7. 最大值运算符</strong><br> 语法格式为：GREATEST(值1，值2，...，值n)。其中，n表示参数列表中有n个值。当有两个或多个参数时，返回值为最大值。假如任意一个自变量为NULL，则GREATEST()的返回值为NULL。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#56B6C2;"> GREATEST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">), </span><span style="color:#56B6C2;">GREATEST</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#56B6C2;">GREATEST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------------+-----------------------+--------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#56B6C2;">GREATEST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) | </span><span style="color:#56B6C2;">GREATEST</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">) | </span><span style="color:#56B6C2;">GREATEST</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">,</span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">) |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------------+-----------------------+--------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|               </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> | c                     |               </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------------+-----------------------+--------------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>由结果可以看到，当参数中是整数或者浮点数时，GREATEST将返回其中最大的值；当参数为字符串时，返回字母表中顺序最靠后的字符；当比较值列表中有NULL时，不能判断大小，返回值为NULL。</p><p><strong>8. BETWEEN AND运算符</strong><br> BETWEEN运算符使用的格式通常为SELECT D FROM TABLE WHERE C BETWEEN A AND B，此时，当C大于或等于A，并且C小于或等于B时，结果为1，否则结果为0。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 0</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">10</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 11</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 12</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;c&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+----------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 0</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">10</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 11</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 12</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#C678DD;"> AND</span><span style="color:#98C379;"> &#39;c&#39;</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+----------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                 </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |                    </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |                       </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------------------+----------------------+-------------------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> last_name, salary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  salary </span><span style="color:#C678DD;">BETWEEN</span><span style="color:#D19A66;"> 2500</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 3500</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>9. IN运算符</strong><br> IN运算符用于判断给定的值是否是IN列表中的一个值，如果是则返回1，否则返回0。如果给定的值为NULL，或者IN列表中存在NULL，则结果为NULL。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">), </span><span style="color:#C678DD;">NULL</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------------------+------------+-------------------+--------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">) | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) | </span><span style="color:#C678DD;">NULL</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">) | </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">) |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------------------+------------+-------------------+--------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|            </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">         |        </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">   |         </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">      |         </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">          |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------------------+------------+-------------------+--------------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id, last_name, salary, manager_id</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  manager_id </span><span style="color:#C678DD;">IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">100</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">101</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">201</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>10. NOT IN运算符</strong><br> NOT IN运算符用于判断给定的值是否不是IN列表中的一个值，如果不是IN列表中的一个值，则返回1，否则返回0。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;a&#39;</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">), </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------+----------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;a&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;b&#39;</span><span style="color:#ABB2BF;">,</span><span style="color:#98C379;">&#39;c&#39;</span><span style="color:#ABB2BF;">) | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> NOT</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">3</span><span style="color:#ABB2BF;">) |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------+----------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                 </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">        |            </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">   |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------+----------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>11. LIKE运算符</strong><br> LIKE运算符主要用来匹配字符串，通常用于模糊匹配，如果满足条件则返回1，否则返回0。如果给定的值或者匹配条件为NULL，则返回结果为NULL。</p><p>LIKE运算符通常使用如下通配符：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">“%”：匹配0个或多个字符。</span></span>
<span class="line"><span style="color:#ABB2BF;">“_”：只能匹配一个字符。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>SQL语句示例如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> NULL</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;abc&#39;</span><span style="color:#C678DD;"> LIKE</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;  </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------------+-----------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#C678DD;">NULL</span><span style="color:#C678DD;"> LIKE</span><span style="color:#98C379;"> &#39;abc&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;abc&#39;</span><span style="color:#C678DD;"> LIKE</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------------+-----------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|          </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">   |          </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">   |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-----------------+-----------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;">	first_name</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> 	employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">	first_name </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;S%&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> last_name</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  last_name </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;_o%&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>ESCAPE</strong></p><ul><li>回避特殊符号的：<strong>使用转义符</strong>。例如：将[%]转为[4%]、[]转为[4]，然后再加上[ESCAPE‘4’]即可。</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> job_id</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   jobs</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  job_id </span><span style="color:#C678DD;">LIKE</span><span style="color:#ABB2BF;"> ‘IT\\_%‘;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>如果使用\\表示转义，要省略ESCAPE。如果不是\\，则要加上ESCAPE。</li></ul><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> job_id</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   jobs</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  job_id </span><span style="color:#C678DD;">LIKE</span><span style="color:#ABB2BF;"> ‘IT4_%‘ escape ‘</span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;">‘;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>12. REGEXP运算符</strong></p><p>REGEXP运算符用来匹配字符串，语法格式为：<code>expr REGEXP 匹配条件</code>。如果expr满足匹配条件，返回1；如果不满足，则返回0。若expr或匹配条件任意一个为NULL，则结果为NULL。</p><p>REGEXP运算符在进行匹配时，常用的有下面几种通配符：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>（1）‘^’匹配以该字符后面的字符开头的字符串。</span></span>
<span class="line"><span>（2）‘4’匹配以该字符前面的字符结尾的字符串。</span></span>
<span class="line"><span>（3）‘.’匹配任何一个单字符。</span></span>
<span class="line"><span>（4）“[...]”匹配在方括号内的任何字符。例如，“[abc]”匹配“a”或“b”或“c”。为了命名字符的范围，使用一个‘-’。“[a-z]”匹配任何字母，而“[0-9]”匹配任何数字。</span></span>
<span class="line"><span>（5）‘*’匹配零个或多个在它前面的字符。例如，“x*”匹配任何数量的‘x’字符，“[0-9]*”匹配任何数量的数字，而“*”匹配任何数量的任何字符。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>SQL语句示例如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;shkstart&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;^s&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;shkstart&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;t4&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;shkstart&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;hk&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------+------------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#98C379;">&#39;shkstart&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;^s&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;shkstart&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;t4&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;shkstart&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;hk&#39;</span><span style="color:#ABB2BF;">  |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------+------------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                      </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |                      </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |                       </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">------------------------+------------------------+-------------------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">01</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#98C379;"> &#39;atguigu&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;gu.gu&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;atguigu&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;[ab]&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#98C379;">&#39;atguigu&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;gu.gu&#39;</span><span style="color:#ABB2BF;"> | </span><span style="color:#98C379;">&#39;atguigu&#39;</span><span style="color:#ABB2BF;"> REGEXP </span><span style="color:#98C379;">&#39;[ab]&#39;</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------+-------------------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|                        </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |                       </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------------------------+-------------------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_3-逻辑运算符" tabindex="-1"><a class="header-anchor" href="#_3-逻辑运算符"><span>3. 逻辑运算符</span></a></h2><p>逻辑运算符主要用来判断表达式的真假，在MySQL中，逻辑运算符的返回结果为1、0或者NULL。</p><p>MySQL中支持4种逻辑运算符如下：</p><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012110241418.png" alt="image-20211012110241418" tabindex="0" loading="lazy"><figcaption>image-20211012110241418</figcaption></figure><p><strong>1．逻辑非运算符</strong><br> 逻辑非（NOT或!）运算符表示当给定的值为0时返回1；当给定的值为非0值时返回0；当给定的值为NULL时，返回NULL。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#C678DD;"> NOT</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NOT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NOT</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">), </span><span style="color:#C678DD;">NOT</span><span style="color:#ABB2BF;"> !</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;">;    </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+-------+----------+--------+----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#C678DD;">NOT</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NOT</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NOT</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">+</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">) | </span><span style="color:#C678DD;">NOT</span><span style="color:#ABB2BF;"> !</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NOT NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+-------+----------+--------+----------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|     </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |        </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |     </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">-------+-------+----------+--------+----------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> warning (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> last_name, job_id</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  job_id </span><span style="color:#C678DD;">NOT</span><span style="color:#C678DD;"> IN</span><span style="color:#ABB2BF;"> (</span><span style="color:#98C379;">&#39;IT_PROG&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;ST_CLERK&#39;</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&#39;SA_REP&#39;</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>2．逻辑与运算符</strong><br> 逻辑与（AND或&amp;&amp;）运算符是当给定的所有值均为非0值，并且都不为NULL时，返回1；当给定的一个值或者多个值为0时则返回0；否则返回NULL。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------+---------+------------+------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">0</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> AND</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------+---------+------------+------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|        </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |       </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |          </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |       </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------+---------+------------+------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id, last_name, job_id, salary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  salary </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;">10000</span></span>
<span class="line"><span style="color:#C678DD;">AND</span><span style="color:#ABB2BF;">    job_id </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;%MAN%&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3．逻辑或运算符</strong><br> 逻辑或（OR或||）运算符是当给定的值都不为NULL，并且任何一个值为非0值时，则返回1，否则返回0；当一个值为NULL，并且另一个值为非0值时，返回1，否则返回NULL；当两个值都为NULL时，返回NULL。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#C678DD;"> OR</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> OR</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> OR</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> || </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> || </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">;     </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------+--------+-----------+-----------+--------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> OR</span><span style="color:#ABB2BF;"> -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> OR</span><span style="color:#D19A66;"> 0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> OR</span><span style="color:#C678DD;"> NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> || </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> || </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------+--------+-----------+-----------+--------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|       </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |         </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |    </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">   |       </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">   |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------+--------+-----------+-----------+--------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;"> warnings (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">#查询基本薪资不在9000-12000之间的员工编号和基本薪资</span></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#C678DD;"> NOT</span><span style="color:#ABB2BF;"> (salary </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 9000</span><span style="color:#C678DD;"> AND</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">&lt;=</span><span style="color:#D19A66;"> 12000</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">&lt;</span><span style="color:#D19A66;">9000</span><span style="color:#C678DD;"> OR</span><span style="color:#ABB2BF;"> salary </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 12000</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id,salary </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> employees </span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> salary </span><span style="color:#C678DD;">NOT</span><span style="color:#C678DD;"> BETWEEN</span><span style="color:#D19A66;"> 9000</span><span style="color:#C678DD;"> AND</span><span style="color:#D19A66;"> 12000</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">SELECT</span><span style="color:#ABB2BF;"> employee_id, last_name, job_id, salary</span></span>
<span class="line"><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;">   employees</span></span>
<span class="line"><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;">  salary </span><span style="color:#56B6C2;">&gt;=</span><span style="color:#D19A66;"> 10000</span></span>
<span class="line"><span style="color:#C678DD;">OR</span><span style="color:#ABB2BF;">     job_id </span><span style="color:#C678DD;">LIKE</span><span style="color:#98C379;"> &#39;%MAN%&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>注意：</p><p>OR可以和AND一起使用，但是在使用时要注意两者的优先级，由于AND的优先级高于OR，因此先对AND两边的操作数进行操作，再与OR中的操作数结合。</p></blockquote><p><strong>4．逻辑异或运算符</strong><br> 逻辑异或（XOR）运算符是当给定的值中任意一个值为NULL时，则返回NULL；如果两个非NULL的值都是0或者都不等于0时，则返回0；如果一个值为0，另一个值不为0时，则返回1。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> XOR -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------+---------+---------+------------+---------------+---------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR -</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> XOR </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------+---------+---------+------------+---------------+---------------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|        </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |       </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |       </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |       </span><span style="color:#C678DD;">NULL</span><span style="color:#ABB2BF;"> |             </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |             </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">----------+---------+---------+------------+---------------+---------------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#C678DD;">select</span><span style="color:#ABB2BF;"> last_name,department_id,salary </span></span>
<span class="line"><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> employees</span></span>
<span class="line"><span style="color:#C678DD;">where</span><span style="color:#ABB2BF;"> department_id </span><span style="color:#C678DD;">in</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;">) XOR salary </span><span style="color:#56B6C2;">&gt;</span><span style="color:#D19A66;"> 8000</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_4-位运算符" tabindex="-1"><a class="header-anchor" href="#_4-位运算符"><span>4. 位运算符</span></a></h2><p>位运算符是在二进制数上进行计算的运算符。位运算符会先将操作数变成二进制数，然后进行位运算，最后将计算结果从二进制变回十进制数。</p><p>MySQL支持的位运算符如下：</p><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012110511223.png" alt="image-20211012110511223" tabindex="0" loading="lazy"><figcaption>image-20211012110511223</figcaption></figure><p><strong>1．按位与运算符</strong><br> 按位与（&amp;）运算符将给定值对应的二进制数逐位进行逻辑与运算。当给定值对应的二进制位的数值都为1时，则该位返回1，否则返回0。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> &amp; </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> &amp; </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> &amp; </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> &amp; </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>1的二进制数为0001，10的二进制数为1010，所以1 &amp; 10的结果为0000，对应的十进制数为0。20的二进制数为10100，30的二进制数为11110，所以20 &amp; 30的结果为10100，对应的十进制数为20。</p><p><strong>2. 按位或运算符</strong><br> 按位或（|）运算符将给定的值对应的二进制数逐位进行逻辑或运算。当给定值对应的二进制位的数值有一个或两个为1时，则该位返回1，否则返回0。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">; </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|     </span><span style="color:#D19A66;">11</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>1的二进制数为0001，10的二进制数为1010，所以1 | 10的结果为1011，对应的十进制数为11。20的二进制数为10100，30的二进制数为11110，所以20 | 30的结果为11110，对应的十进制数为30。</p><p><strong>3. 按位异或运算符</strong><br> 按位异或（^）运算符将给定的值对应的二进制数逐位进行逻辑异或运算。当给定值对应的二进制位的数值不同时，则该位返回1，否则返回0。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#ABB2BF;"> ^ </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> ^ </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;">; </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> ^ </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">20</span><span style="color:#ABB2BF;"> ^ </span><span style="color:#D19A66;">30</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|     </span><span style="color:#D19A66;">11</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+---------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>1的二进制数为0001，10的二进制数为1010，所以1 ^ 10的结果为1011，对应的十进制数为11。20的二进制数为10100，30的二进制数为11110，所以20 ^ 30的结果为01010，对应的十进制数为10。</p><p>再举例：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 12</span><span style="color:#ABB2BF;"> &amp; </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;">,</span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> ^ </span><span style="color:#D19A66;">5</span><span style="color:#C678DD;"> FROM</span><span style="color:#ABB2BF;"> DUAL;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+--------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> &amp; </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">12</span><span style="color:#ABB2BF;"> ^ </span><span style="color:#D19A66;">5</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+--------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">13</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">9</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+--------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211023115738415.png" alt="image-20211023115738415" style="zoom:80%;"><p><strong>4. 按位取反运算符</strong><br> 按位取反（~）运算符将给定的值的二进制数逐位进行取反操作，即将1变为0，将0变为1。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 10</span><span style="color:#ABB2BF;"> &amp; ~</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;"> &amp; ~</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">10</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">---------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>由于按位取反（~）运算符的优先级高于按位与（&amp;）运算符的优先级，所以10 &amp; ~1，首先，对数字1进行按位取反操作，结果除了最低位为0，其他位都为1，然后与10进行按位与操作，结果为10。</p><p><strong>5. 按位右移运算符</strong><br> 按位右移（&gt;&gt;）运算符将给定的值的二进制数的所有位右移指定的位数。右移指定的位数后，右边低位的数值被移出并丢弃，左边高位空出的位置用0补齐。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#56B6C2;"> &gt;&gt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4</span><span style="color:#56B6C2;"> &gt;&gt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &gt;&gt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">4</span><span style="color:#56B6C2;"> &gt;&gt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;"> |      </span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>1的二进制数为0000 0001，右移2位为0000 0000，对应的十进制数为0。4的二进制数为0000 0100，右移2位为0000 0001，对应的十进制数为1。</p><p><strong>6. 按位左移运算符</strong><br> 按位左移（&lt;&lt;）运算符将给定的值的二进制数的所有位左移指定的位数。左移指定的位数后，左边高位的数值被移出并丢弃，右边低位空出的位置用0补齐。</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#D19A66;"> 1</span><span style="color:#56B6C2;"> &lt;&lt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;">4</span><span style="color:#56B6C2;"> &lt;&lt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;">;  </span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+</span></span>
<span class="line"><span style="color:#ABB2BF;">| </span><span style="color:#D19A66;">1</span><span style="color:#56B6C2;"> &lt;&lt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;"> | </span><span style="color:#D19A66;">4</span><span style="color:#56B6C2;"> &lt;&lt;</span><span style="color:#D19A66;"> 2</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+</span></span>
<span class="line"><span style="color:#ABB2BF;">|      </span><span style="color:#D19A66;">4</span><span style="color:#ABB2BF;"> |     </span><span style="color:#D19A66;">16</span><span style="color:#ABB2BF;"> |</span></span>
<span class="line"><span style="color:#ABB2BF;">+</span><span style="color:#7F848E;font-style:italic;">--------+--------+</span></span>
<span class="line"><span style="color:#D19A66;">1</span><span style="color:#C678DD;"> row</span><span style="color:#C678DD;"> in</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;"> (</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>1的二进制数为0000 0001，左移两位为0000 0100，对应的十进制数为4。4的二进制数为0000 0100，左移两位为0001 0000，对应的十进制数为16。</p><h2 id="_5-运算符的优先级" tabindex="-1"><a class="header-anchor" href="#_5-运算符的优先级"><span>5. 运算符的优先级</span></a></h2><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012111042395.png" alt="image-20211012111042395" tabindex="0" loading="lazy"><figcaption>image-20211012111042395</figcaption></figure><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20211012110731059.png" alt="image-20211012110731059" tabindex="0" loading="lazy"><figcaption>image-20211012110731059</figcaption></figure><p>数字编号越大，优先级越高，优先级高的运算符先进行计算。可以看到，赋值运算符的优先级最低，使用“()”括起来的表达式的优先级最高。</p><h2 id="拓展-使用正则表达式查询" tabindex="-1"><a class="header-anchor" href="#拓展-使用正则表达式查询"><span>拓展：使用正则表达式查询</span></a></h2><p>正则表达式通常被用来检索或替换那些符合某个模式的文本内容，根据指定的匹配模式匹配文本中符合要求的特殊字符串。例如，从一个文本文件中提取电话号码，查找一篇文章中重复的单词或者替换用户输入的某些敏感词语等，这些地方都可以使用正则表达式。正则表达式强大而且灵活，可以应用于非常复杂的查询。</p><p>MySQL中使用REGEXP关键字指定正则表达式的字符匹配模式。下表列出了REGEXP操作符中常用字符匹配列表。</p><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/img/image-20210926151249943.png" alt="image-20210926151249943" tabindex="0" loading="lazy"><figcaption>image-20210926151249943</figcaption></figure><p><strong>1. 查询以特定字符或字符串开头的记录</strong><br> 字符‘^’匹配以特定字符或者字符串开头的文本。</p><p>在fruits表中，查询f_name字段以字母‘b’开头的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;^b&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>2. 查询以特定字符或字符串结尾的记录</strong><br> 字符‘4’匹配以特定字符或者字符串结尾的文本。</p><p>在fruits表中，查询f_name字段以字母‘y’结尾的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;y4&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>3. 用符号&quot;.&quot;来替代字符串中的任意一个字符</strong><br> 字符‘.’匹配任意一个字符。<br> 在fruits表中，查询f_name字段值包含字母‘a’与‘g’且两个字母之间只有一个字母的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;a.g&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>4. 使用&quot;*&quot;和&quot;+&quot;来匹配多个字符</strong><br> 星号‘*’匹配前面的字符任意多次，包括0次。加号‘+’匹配前面的字符至少一次。</p><p>在fruits表中，查询f_name字段值以字母‘b’开头且‘b’后面出现字母‘a’的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;^ba*&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在fruits表中，查询f_name字段值以字母‘b’开头且‘b’后面出现字母‘a’至少一次的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;^ba+&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>5. 匹配指定字符串</strong><br> 正则表达式可以匹配指定字符串，只要这个字符串在查询文本中即可，如要匹配多个字符串，多个字符串之间使用分隔符‘|’隔开。</p><p>在fruits表中，查询f_name字段值包含字符串“on”的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;on&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在fruits表中，查询f_name字段值包含字符串“on”或者“ap”的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;on|ap&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>之前介绍过，LIKE运算符也可以匹配指定的字符串，但与REGEXP不同，LIKE匹配的字符串如果在文本中间出现，则找不到它，相应的行也不会返回。REGEXP在文本内进行匹配，如果被匹配的字符串在文本中出现，REGEXP将会找到它，相应的行也会被返回。对比结果如下所示。</p><p>在fruits表中，使用LIKE运算符查询f_name字段值为“on”的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name </span><span style="color:#C678DD;">like</span><span style="color:#98C379;"> &#39;on&#39;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">Empty</span><span style="color:#C678DD;"> set</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">.</span><span style="color:#D19A66;">00</span><span style="color:#ABB2BF;"> sec)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>6. 匹配指定字符中的任意一个</strong><br> 方括号“[]”指定一个字符集合，只匹配其中任何一个字符，即为所查找的文本。</p><p>在fruits表中，查找f_name字段中包含字母‘o’或者‘t’的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;[ot]&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在fruits表中，查询s_id字段中包含4、5或者6的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> s_id REGEXP </span><span style="color:#98C379;">&#39;[456]&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>7. 匹配指定字符以外的字符</strong><br><code>“[^字符集合]”</code>匹配不在指定集合中的任何字符。</p><p>在fruits表中，查询f_id字段中包含字母a<sub>e和数字1</sub>2以外字符的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_id REGEXP </span><span style="color:#98C379;">&#39;[^a-e1-2]&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>8. 使用{n,}或者{n,m}来指定字符串连续出现的次数</strong><br> “字符串{n,}”表示至少匹配n次前面的字符；“字符串{n,m}”表示匹配前面的字符串不少于n次，不多于m次。例如，a{2,}表示字母a连续出现至少2次，也可以大于2次；a{2,4}表示字母a连续出现最少2次，最多不能超过4次。</p><p>在fruits表中，查询f_name字段值出现字母‘x’至少2次的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;x{2,}&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在fruits表中，查询f_name字段值出现字符串“ba”最少1次、最多3次的记录，SQL语句如下：</p><div class="language-sql line-numbers-mode" data-highlighter="shiki" data-ext="sql" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-sql"><span class="line"><span style="color:#ABB2BF;">mysql</span><span style="color:#56B6C2;">&gt;</span><span style="color:#C678DD;"> SELECT</span><span style="color:#ABB2BF;"> * </span><span style="color:#C678DD;">FROM</span><span style="color:#ABB2BF;"> fruits </span><span style="color:#C678DD;">WHERE</span><span style="color:#ABB2BF;"> f_name REGEXP </span><span style="color:#98C379;">&#39;ba{1,3}&#39;</span><span style="color:#ABB2BF;">;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><figure><img src="https://gaoziman.oss-cn-hangzhou.aliyuncs.com/LeoPic202312031906036.png" alt="公众号封面" tabindex="0" loading="lazy"><figcaption>公众号封面</figcaption></figure>`,163)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};